def ins(S, dopo_tit, nuove):
    i = next(k for k, x in enumerate(S) if x.get('tit') == dopo_tit)
    S[i + 1:i + 1] = nuove

ins(S5, "Dati primari, dati secondari e allocazione", [
 {"t": "esempio", "tit": "Esempio guidato · L’allocazione su una linea condivisa", "lead": "Una linea produce due articoli: come ripartire l’energia (valori illustrativi).",
  "passi": [["Dati della linea", "La linea consuma 30.000 kWh al mese e produce 8 t dell’articolo A e 2 t dell’articolo B.", "30.000 kWh · 8 t A · 2 t B"],
            ["Prima scelta: evitare l’allocazione", "Se un contatore dedicato misura l’energia di ciascun articolo, si usano i dati misurati e non serve ripartire.", "Suddivisione del processo"],
            ["Relazione fisica", "Senza contatori dedicati si ripartisce per massa: A pesa l’80% della produzione.", "A: 24.000 kWh · B: 6.000 kWh"],
            ["Emissioni per tonnellata", "Con il fattore ISPRA 0,1926 kg CO₂/kWh.", "A: 24.000 × 0,1926 ÷ 8 = 578 kg CO₂ per tonnellata (uguale per B)"],
            ["Relazione economica, solo come ultima scelta", "Se B valesse molto più di A, la ripartizione per valore gli attribuirebbe più emissioni: si usa solo se le relazioni fisiche non sono applicabili.", "Gerarchia: evitare → fisica → economica"]],
  "rif": "UNI EN ISO 14067:2018 · UNI EN ISO 14044",
  "nar": "Una linea produce due articoli e consuma trentamila chilowattora al mese. Prima di tutto, se hai contatori dedicati, usi i dati misurati e non devi ripartire nulla. Se non li hai, ripartisci con una relazione fisica, per esempio la massa: l’articolo A pesa l’ottanta per cento della produzione e riceve ventiquattromila chilowattora. Con il fattore ISPRA ottieni circa cinquecentosettantotto chilogrammi di anidride carbonica per tonnellata. Solo se nessuna relazione fisica è applicabile si passa alla relazione economica, che attribuisce più emissioni ai prodotti di maggior valore."},
 {"t": "caso", "tit": "Caso · Il dato del fornitore o la banca dati?",
  "scena": "Per il granulo che acquisti hai due dati: un valore medio di banca dati e una carbon footprint del fornitore, dalla culla al cancello, verificata secondo la UNI EN ISO 14067, più bassa del 25%.",
  "domanda": "Quale dato usi nel tuo studio?",
  "opz": [["Il dato del fornitore, verificato e specifico, dichiarandone la fonte", True, "Corretto: un dato specifico e verificato descrive meglio il tuo sistema; lo dichiari nel rapporto."], ["Sempre il dato di banca dati, perché è più prudente", False, "I dati generici sono un ripiego quando mancano dati specifici affidabili."], ["La media dei due valori", False, "Una media tra un dato specifico e uno generico non ha significato."]],
  "rif": "UNI EN ISO 14067:2018",
  "nar": "Hai due dati per la stessa materia prima. Scegli quale usare e perché."}])
ins(S6, "Trasporti e prodotti venduti", [
 {"t": "esempio", "tit": "Esempio guidato · Le spedizioni ai clienti", "lead": "Metodo basato sulla distanza (fattore illustrativo).",
  "passi": [["Dati di attività", "Nell’anno spedisci 1.200 t di prodotto, con una distanza media di 350 km su camion.", "1.200 t · 350 km"],
            ["Tonnellate chilometro", "Massa per distanza.", "1.200 × 350 = 420.000 t·km"],
            ["Fattore", "Fattore illustrativo per camion pesante: 0,08 kg CO₂e per t·km (da sostituire con la fonte scelta).", "0,08 kg CO₂e/t·km"],
            ["Emissioni", "Tonnellate chilometro per fattore.", "420.000 × 0,08 = 33.600 kg = 33,6 t CO₂e"],
            ["Categoria", "Se il trasporto lo paghi tu è categoria 4; se lo paga il cliente, categoria 9.", "Dichiarare chi paga e la fonte del fattore"]],
  "rif": "GHG Protocol Scope 3 Standard",
  "nar": "Calcoliamo le emissioni delle spedizioni ai clienti con il metodo della distanza. Spedisci milleduecento tonnellate di prodotto, con una distanza media di trecentocinquanta chilometri. Moltiplichi massa e distanza: quattrocentoventimila tonnellate chilometro. Con un fattore illustrativo di zero virgola zero otto chilogrammi per tonnellata chilometro ottieni trentatré virgola sei tonnellate di anidride carbonica equivalente. Nel tuo inventario sostituirai il fattore con quello della fonte scelta, dichiarandola, e collocherai il risultato nella categoria quattro o nove a seconda di chi paga il trasporto."},
 {"t": "caso", "tit": "Caso · Chi paga il trasporto?",
  "scena": "Vendi con resa franco destino: il trasporto fino al magazzino del cliente lo organizza e lo paga la tua azienda tramite un corriere.",
  "domanda": "In quale categoria dello Scope 3 collochi queste emissioni?",
  "opz": [["Categoria 4: trasporto e distribuzione pagati dall’azienda", True, "Corretto: nel GHG Protocol i trasporti pagati dall’organizzazione, anche verso i clienti, rientrano nella categoria 4."], ["Categoria 9: trasporto a valle", False, "La categoria 9 riguarda i trasporti a valle non pagati dall’organizzazione."], ["Scope 1", False, "Il mezzo è del corriere: non è un’emissione diretta."]],
  "rif": "GHG Protocol Scope 3 Standard",
  "nar": "Un dettaglio che confonde molti: chi paga il trasporto decide la categoria. Leggi il caso e scegli."}])
ins(S7, "Dal piano agli indicatori", [
 {"t": "esempio", "tit": "Esempio guidato · Intensità e valori assoluti", "lead": "Quando un indicatore migliora ma le emissioni crescono.",
  "passi": [["Anno base 2024", "419 t CO₂e e 2.000 t di prodotto.", "Intensità: 419 ÷ 2.000 = 0,210 t CO₂e per tonnellata"],
            ["Anno 2027", "Produzione cresciuta a 2.600 t; emissioni 470 t CO₂e.", "Intensità: 470 ÷ 2.600 = 0,181 t CO₂e per tonnellata"],
            ["Lettura dell’intensità", "L’intensità è scesa di circa il 14%: l’efficienza è migliorata.", "(0,210 − 0,181) ÷ 0,210 ≈ −14%"],
            ["Lettura assoluta", "Le emissioni sono aumentate di 51 t: per il clima conta questo dato.", "470 − 419 = +51 t CO₂e (+12%)"],
            ["Come comunicarlo", "Si riportano entrambi gli indicatori, senza presentare il calo di intensità come riduzione delle emissioni.", "Assoluto e intensità, sempre insieme"]],
  "rif": "UNI EN ISO 14064-1:2019",
  "nar": "Un caso frequente. Nell’anno base lo stabilimento emette quattrocentodiciannove tonnellate producendo duemila tonnellate: l’intensità è zero virgola duecentodieci. Tre anni dopo la produzione è salita a duemilaseicento tonnellate e le emissioni a quattrocentosettanta: l’intensità è scesa a zero virgola centottantuno, circa il quattordici per cento in meno. Ma le emissioni assolute sono aumentate di cinquantuno tonnellate, il dodici per cento in più. Per il clima conta il valore assoluto. Nel rapporto riporti entrambi gli indicatori e non presenti il miglioramento dell’intensità come una riduzione delle emissioni."},
 {"t": "caso", "tit": "Caso · L’obiettivo di intensità",
  "scena": "La direzione propone come unico obiettivo «−30% di intensità al 2030». Il piano industriale prevede di raddoppiare la produzione entro il 2030.",
  "domanda": "Che cosa osservi?",
  "opz": [["L’obiettivo va bene: l’intensità misura l’efficienza", False, "Con la produzione raddoppiata, −30% di intensità significa emissioni assolute in aumento del 40%."], ["Va affiancato da un obiettivo assoluto: con la produzione raddoppiata, −30% di intensità equivale a +40% di emissioni", True, "Corretto: 2 × 0,7 = 1,4, cioè emissioni aumentate del 40%."], ["Basta portarlo a −35%", False, "Anche così le emissioni assolute crescerebbero del 30%."]],
  "rif": "SBTi Corporate Net-Zero Standard",
  "nar": "La direzione propone un obiettivo di intensità. Verifica che cosa significa in valori assoluti."},
 {"t": "vf", "tit": "Leve e obiettivi", "voci": [
   ["Riparare le perdite di aria compressa riduce le emissioni di Scope 2.", True, "Vero: diminuiscono i consumi elettrici."],
   ["Acquistare crediti di compensazione riduce le emissioni dell’inventario.", False, "Falso: l’inventario resta invariato; i crediti si riportano separatamente."],
   ["Un sistema di gestione dell’energia aiuta a mantenere il miglioramento nel tempo.", True, "Vero: per esempio secondo la UNI CEI EN ISO 50001."]],
  "nar": "Tre affermazioni su leve e obiettivi: vere o false?"}])
