ins(S8, "I questionari dei clienti", [
 {"t": "esempio", "tit": "Esempio guidato · La scheda unica per i clienti", "lead": "Un solo documento, aggiornato una volta l’anno, per tutti i questionari.",
  "passi": [["Identità e perimetro", "Ragione sociale, siti inclusi, approccio di consolidamento, anno di rendicontazione.", "Controllo operativo · anno 2024"],
            ["Inventario", "Scope 1, Scope 2 location-based e market-based, Scope 3 per categoria con metodo e qualità dei dati.", "Es.: 303,6 · 115,6 / 126,1 t CO₂e · Scope 3 stimato con la spesa"],
            ["Fattori e fonti", "Tabelle nazionali, ISPRA, mix residuale, serie di GWP: con edizione e anno.", "MASE 2021–2023 · ISPRA 430/2026 · AIB 2025 · IPCC AR6"],
            ["Obiettivi e azioni", "Obiettivo assoluto con anno base e anno target, azioni principali e stato di avanzamento.", "Es.: −30% Scope 1 e 2 al 2030 rispetto al 2024"],
            ["Prodotti e verifica", "Carbon footprint dei prodotti principali con confini e norma; eventuale verifica di parte terza.", "UNI EN ISO 14067 · UNI EN ISO 14064-3"]],
  "rif": "Raccomandazione (UE) 2025/1710 · UNI EN ISO 14064-1:2019",
  "nar": "Ecco come costruire la scheda unica per i clienti. In apertura identità e perimetro: siti inclusi, approccio di consolidamento, anno. Poi l’inventario, con lo Scope due secondo entrambi i metodi e lo Scope tre per categoria, dichiarando metodo e qualità dei dati. Poi i fattori e le fonti, con edizione e anno. Quindi obiettivi e azioni, e infine la carbon footprint dei prodotti principali e l’eventuale verifica. Aggiornata una volta l’anno, ti permette di rispondere a qualsiasi questionario in modo rapido e coerente."},
 {"t": "caso", "tit": "Caso · Due questionari, due numeri",
  "scena": "Un cliente segnala che nel suo questionario hai indicato 420 t CO₂e per Scope 1 e 2, mentre a un altro cliente del suo gruppo hai indicato 330 t per lo stesso anno.",
  "domanda": "Qual è la causa più probabile e come rimedi?",
  "opz": [["Metodi diversi per lo Scope 2 non dichiarati: rispondi con la scheda unica indicando entrambi i metodi", True, "Corretto: la differenza tra location-based e market-based va sempre dichiarata, con entrambi i valori."], ["Errori di battitura: correggi il valore più alto", False, "Prima di correggere, verifica la causa: spesso è il metodo dello Scope 2 o il perimetro."], ["Non serve rimediare: i questionari sono diversi", False, "Numeri incoerenti per lo stesso anno minano la credibilità dei dati."]],
  "rif": "GHG Protocol Scope 2 Guidance",
  "nar": "Un cliente ti segnala due numeri diversi per lo stesso anno. Trova la causa e rimedia."},
 {"t": "vf", "tit": "Filiera e questionari", "voci": [
   ["Il VSME è uno standard obbligatorio per tutte le PMI.", False, "Falso: è uno standard volontario raccomandato dalla Commissione."],
   ["In un questionario conviene indicare lo Scope 2 con entrambi i metodi.", True, "Vero."],
   ["Una carbon footprint di prodotto si comunica con valore, unità, confini e norma.", True, "Vero."]],
  "nar": "Tre affermazioni su filiera e questionari: vere o false?"}])

